begin;
update materiais set conteudo_html=replace(replace(conteudo_html,'@@CSS@@','<style>
@import url(''https://fonts.googleapis.com/css2?family=Arimo:wght@600;700&family=Inter:wght@400;500;600&display=swap'');
*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,sans-serif;color:#13203a;background:#fbf9f4;line-height:1.55;font-size:16px}
.w{max-width:760px;margin:0 auto;padding:28px 22px 36px}
.k{font-size:12px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#9a7a2e;margin:0 0 6px}
h1{font-family:Arimo,sans-serif;font-size:28px;line-height:1.15;margin:0 0 10px}
h2{font-family:Arimo,sans-serif;font-size:20px;margin:28px 0 10px}
p{margin:0 0 12px}.lead{font-size:17px;color:#3c4a66}
.frases{display:grid;gap:10px;margin:8px 0}
.f{background:#fff;border:1px solid #e6dfcf;border-radius:14px;padding:12px 16px;border-left:4px solid #d9b866}
.f b{display:block;font-size:17px;color:#0e1b33}.f span{font-size:14px;color:#5b6780}
.dica{background:linear-gradient(155deg,#1d3766,#0e1b33);color:#f4efe2;border-radius:16px;padding:16px 18px;margin:18px 0}
.dica .k{color:#e9cf8a}.dica p{margin:0}
.cmp{display:grid;grid-template-columns:1fr 1fr;gap:10px}.cmp div{border-radius:12px;padding:10px 14px;font-size:15px}
.cmp .n{background:#fbecea;color:#7a2a1f}.cmp .s{background:#eaf4ec;color:#1f5a32}
.q{background:#fff;border:1px solid #e6dfcf;border-radius:14px;padding:14px 16px;margin:10px 0}
.q p{font-weight:600;margin-bottom:8px}.q button{display:block;width:100%;text-align:left;font:inherit;font-size:15px;background:#fbf9f4;border:1px solid #e0d8c6;border-radius:10px;padding:9px 12px;margin:6px 0;cursor:pointer}
.q button.ok{background:#eaf4ec;border-color:#5aa36f}.q button.no{background:#fbecea;border-color:#d98a7c}
.q .r{font-size:14px;color:#3c4a66;min-height:1px}
.desafio{border:1.5px dashed #c9a24d;border-radius:16px;padding:16px 18px;margin-top:22px;background:#fffdf7}
ol,ul{padding-left:20px;margin:0 0 12px}li{margin:4px 0}
.mail{background:#fff;border:1px solid #e6dfcf;border-radius:14px;padding:16px 18px;font-size:15px}.mail .as{font-weight:600;border-bottom:1px solid #eee;padding-bottom:8px;margin-bottom:10px}
</style>'),'@@JS@@','<script>document.querySelectorAll(''.q'').forEach(q=>{q.querySelectorAll(''button'').forEach(b=>b.onclick=()=>{q.querySelectorAll(''button'').forEach(x=>x.className='''');const ok=b.dataset.ok===''1'';b.className=ok?''ok'':''no'';q.querySelector(''.r'').textContent=ok?''✓ ''+(q.dataset.ok||''Isso!''):''✗ ''+(q.dataset.no||''Quase. Tente de novo.'');})})</script>') where conteudo_html like '%@@CSS@@%';
