insert into material_turmas(material_id,turma_id) values('ad3e18e0-178c-4f0c-ad57-a311c778120a','cae5ea78-362c-42b3-8450-ff368f910b47');
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('a6e37718-c86b-4bee-bb89-8411e675f19a','db722b21-0d39-4cc8-9ac7-03c9ef25654c','bcc9ec74-7b6f-49de-9765-6b7b43b66f9c','html','Frases-chave para se apresentar','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 1 · Frases-chave</p><h1>Frases para se apresentar</h1><p class=''lead''>Uma boa apresentação profissional tem três tempos: o que você faz hoje, de onde vem e para onde vai.</p><h2>Hoje</h2><div class=''frases''><div class=''f''><b>Me dedico a la gestión de proyectos.</b><span>Eu trabalho com gestão de projetos.</span></div><div class=''f''><b>Estoy a cargo del equipo comercial para LATAM.</b><span>Sou responsável pelo time comercial para a América Latina.</span></div><div class=''f''><b>Trabajo en el área de finanzas de una empresa de logística.</b><span>Trabalho na área de finanças de uma empresa de logística.</span></div></div><h2>De onde vem</h2><div class=''frases''><div class=''f''><b>Llevo diez años en el sector.</b><span>Estou há dez anos no setor.</span></div><div class=''f''><b>Antes trabajé en consultoría.</b><span>Antes trabalhei com consultoria.</span></div></div><h2>Para onde vai</h2><div class=''frases''><div class=''f''><b>Mi objetivo ahora es abrir nuevos mercados.</b><span>Meu objetivo agora é abrir novos mercados.</span></div><div class=''f''><b>Me interesa mucho conocer cómo trabajan ustedes.</b><span>Tenho muito interesse em entender como vocês trabalham.</span></div></div><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Em espanhol, “trabajo con marketing” soa traduzido. Prefira <b>me dedico al marketing</b> ou <b>trabajo en marketing</b>.</p></div></div>@@JS@@</body></html>',null,2,'espanhol',false);
insert into material_turmas(material_id,turma_id) values('a6e37718-c86b-4bee-bb89-8411e675f19a','cae5ea78-362c-42b3-8450-ff368f910b47');
insert into fases(id,materia_id,titulo,ordem) values('dfa86d12-be33-42f9-942e-997ca57f0deb','db722b21-0d39-4cc8-9ac7-03c9ef25654c','Praticar',1);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('e20b1889-997e-4bea-ad7e-3d8b09916bcb','db722b21-0d39-4cc8-9ac7-03c9ef25654c','dfa86d12-be33-42f9-942e-997ca57f0deb','html','Exercício: soa natural?','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 1 · Prática</p><h1>Qual soa mais natural?</h1><p class=''lead''>Escolha a opção que um nativo usaria numa reunião.</p><div class=''q'' data-ok="Llevar + tempo é a forma mais natural." data-no="A primeira está correta, mas soa menos natural. Tente outra."><p>Você quer dizer que está há 5 anos na empresa:</p><button data-ok=''0''>Trabajo en la empresa hace cinco años.</button><button data-ok=''1''>Llevo cinco años en la empresa.</button><button data-ok=''0''>Estoy en la empresa por cinco años.</button><div class=''r''></div></div><div class=''q'' data-ok="Responsable de… é o uso geral." data-no="Quase. Atenção à preposição."><p>Você é responsável pela área de compras:</p><button data-ok=''0''>Soy responsable por compras.</button><button data-ok=''1''>Soy el responsable del área de compras.</button><button data-ok=''0''>Soy encargado con compras.</button><div class=''r''></div></div><div class=''q'' data-ok="Fecha com elegância e abre espaço para perguntas." data-no="Soa abrupto. Tente outra."><p>Para fechar sua apresentação:</p><button data-ok=''0''>Es eso.</button><button data-ok=''1''>Eso es todo, ¿tienen alguna pregunta?</button><button data-ok=''0''>Acabé.</button><div class=''r''></div></div><div class=''desafio''><p class=''k''>Desafio</p><p>Escreva sua apresentação em 4 frases (hoje, antes, agora, objetivo) e leia em voz alta cronometrando 30 segundos.</p></div></div>@@JS@@</body></html>',null,3,'espanhol',false);
