insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('cf2347e4-d84d-4386-9ca0-ffcec81e52f2','db722b21-0d39-4cc8-9ac7-03c9ef25654c','fa483881-887b-45c1-ac69-677ec3c0e7e0','html','Desafio: grave sua apresentação','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 1 · Desafio</p><h1>Grave sua apresentação</h1><ol><li>Use o roteiro: <b>hoy → antes → ahora → objetivo</b>.</li><li>Grave um áudio ou vídeo de até 40 segundos, sem ler.</li><li>Envie na tarefa da semana.</li></ol><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Na próxima aula, a professora simula uma reunião de abertura com cliente e você se apresenta “ao vivo”.</p></div></div>@@JS@@</body></html>',null,4,'espanhol',false);
