insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('16f46ddf-93dc-481d-920f-4002b1115c04','8f94418a-cb25-4310-9915-81589e3113bc','09c1a794-2826-4f61-b1d5-13ad79396e2c','html','Saudações e despedidas','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 2 · Frases-chave</p><h1>Abrir e fechar no tom certo</h1><h2>Abrir</h2><div class=''frases''><div class=''f''><b>Estimada Sra. Pérez:</b><span>Formal, primeiro contato.</span></div><div class=''f''><b>Hola, Carlos:</b><span>Neutro, com quem você já conversa.</span></div><div class=''f''><b>Espero que estés bien.</b><span>Gentil e comum, sem exagero.</span></div></div><h2>Motivo</h2><div class=''frases''><div class=''f''><b>Te escribo para confirmar la reunión del jueves.</b><span>Escrevo para confirmar a reunião de quinta.</span></div><div class=''f''><b>Les comparto la propuesta actualizada.</b><span>Compartilho com vocês a proposta atualizada.</span></div></div><h2>Fechar</h2><div class=''frases''><div class=''f''><b>Quedo atenta a sus comentarios.</b><span>Fico no aguardo dos comentários.</span></div><div class=''f''><b>Un saludo cordial,</b><span>Atenciosamente (neutro).</span></div><div class=''f''><b>Gracias de antemano.</b><span>Desde já, obrigada.</span></div></div><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Em português “fico no aguardo” é natural; em espanhol <b>quedo atento/a</b> ou <b>quedo a la espera</b> fazem esse papel.</p></div></div>@@JS@@</body></html>',null,2,'espanhol',false);
