insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('e92c9502-5aeb-4f7b-a7cb-172766141e13','8f94418a-cb25-4310-9915-81589e3113bc','eecc6da2-3862-4f6b-a87d-3296b49b6a49','html','Antes e depois: um e-mail real','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 2 · Prática</p><h1>Antes e depois</h1><p class=''lead''>O mesmo pedido, escrito por um brasileiro e revisado.</p><div class=''cmp'' style=''margin:8px 0''><div class=''n''>Asunto: Reunión</div><div class=''s''>Asunto: Confirmación de reunión – jueves 10 h</div></div><div class=''cmp'' style=''margin:8px 0''><div class=''n''>Hola, todo bien?</div><div class=''s''>Hola, Carlos: espero que estés bien.</div></div><div class=''cmp'' style=''margin:8px 0''><div class=''n''>Quería saber si podemos marcar la reunión.</div><div class=''s''>Te escribo para confirmar la reunión del jueves a las 10 h.</div></div><div class=''cmp'' style=''margin:8px 0''><div class=''n''>Aguardo retorno.</div><div class=''s''>Quedo atenta a tu confirmación.</div></div><div class=''q'' data-ok="Claro e específico." data-no="Pouco informativo. Tente outra."><p>Qual assunto é mais eficiente?</p><button data-ok=''0''>Asunto: Hola</button><button data-ok=''1''>Asunto: Propuesta comercial – versión 2</button><button data-ok=''0''>Asunto: Importante!!!</button><div class=''r''></div></div><div class=''q'' data-ok="Formal e respeitoso." data-no="Informal demais para o primeiro contato."><p>Para um cliente com quem você nunca falou:</p><button data-ok=''0''>Hola, querido:</button><button data-ok=''1''>Estimado Sr. Gómez:</button><button data-ok=''0''>Buenas, Gómez:</button><div class=''r''></div></div></div>@@JS@@</body></html>',null,3,'espanhol',false);
insert into material_turmas(material_id,turma_id) values('e92c9502-5aeb-4f7b-a7cb-172766141e13','cae5ea78-362c-42b3-8450-ff368f910b47');
insert into fases(id,materia_id,titulo,ordem) values('18175e8f-7210-407c-98a6-85781f5bf790','8f94418a-cb25-4310-9915-81589e3113bc','Aplicar',2);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('a6e1ab72-11c7-411d-af75-64744d04c30c','8f94418a-cb25-4310-9915-81589e3113bc','18175e8f-7210-407c-98a6-85781f5bf790','html','Desafio: responda um e-mail','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 2 · Desafio</p><h1>Responda este e-mail</h1><div class=''mail''><div class=''as''>Asunto: Cambio de fecha</div><p>Hola:</p><p>Lamentablemente no podremos reunirnos el jueves. ¿Les quedaría bien el lunes a la misma hora?</p><p>Saludos,<br>Lucía</p></div><div class=''desafio''><p class=''k''>Desafio</p><p>Responda aceitando o novo horário, confirme a pauta e encerre com uma despedida adequada. Envie na tarefa.</p></div></div>@@JS@@</body></html>',null,4,'espanhol',false);
