insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('9a999c68-4e1e-4ba0-b925-4bb3ed419a8b','8168a604-f693-4f83-9b8a-1cbaaa47c629','124bbded-37fe-4513-807d-3c155c7ad3ad','video','Vídeo: as etapas da negociação',null,'/exemplos/video-negociar.mp4',1,'espanhol',false);
insert into material_turmas(material_id,turma_id) values('9a999c68-4e1e-4ba0-b925-4bb3ed419a8b','cae5ea78-362c-42b3-8450-ff368f910b47');
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('11c16320-df08-436b-af6f-4c62fc4443fe','8168a604-f693-4f83-9b8a-1cbaaa47c629','124bbded-37fe-4513-807d-3c155c7ad3ad','html','Frases para cada etapa','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 3 · Frases-chave</p><h1>Frases para negociar</h1><h2>Propor</h2><div class=''frases''><div class=''f''><b>Les proponemos lo siguiente…</b><span>Propomos o seguinte…</span></div><div class=''f''><b>¿Qué les parecería si ampliamos el plazo?</b><span>O que acham se ampliarmos o prazo?</span></div></div><h2>Responder a uma objeção</h2><div class=''frases''><div class=''f''><b>Entiendo su punto. Sin embargo…</b><span>Entendo seu ponto. No entanto…</span></div><div class=''f''><b>Podemos revisarlo, siempre y cuando…</b><span>Podemos rever, desde que…</span></div></div><h2>Fechar</h2><div class=''frases''><div class=''f''><b>¿Cerramos el trato?</b><span>Fechamos?</span></div><div class=''f''><b>Entonces quedamos así.</b><span>Então fica combinado assim.</span></div><div class=''f''><b>Les envío la propuesta final hoy mismo.</b><span>Envio a proposta final ainda hoje.</span></div></div><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Do preço se diz <b>alto</b> ou <b>bajo</b>; o produto é que é <b>caro</b>. “El precio es un poco alto para nosotros” soa firme e educado.</p></div></div>@@JS@@</body></html>',null,2,'espanhol',false);
insert into material_turmas(material_id,turma_id) values('11c16320-df08-436b-af6f-4c62fc4443fe','cae5ea78-362c-42b3-8450-ff368f910b47');
insert into fases(id,materia_id,titulo,ordem) values('fda45f8c-81a1-48d8-becb-2a290a84c402','8168a604-f693-4f83-9b8a-1cbaaa47c629','Praticar',1);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('acd5a295-895b-4863-9f5e-967d50bc6075','8168a604-f693-4f83-9b8a-1cbaaa47c629','fda45f8c-81a1-48d8-becb-2a290a84c402','html','Exercício: qual a melhor resposta?','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 3 · Prática</p><h1>Qual a melhor resposta?</h1><div class=''q'' data-ok="Você mantém a conversa aberta e descobre o limite do cliente." data-no="Fecha a negociação cedo demais."><p>O cliente diz: “El precio es muy alto”. Você responde:</p><button data-ok=''0''>No puedo hacer nada.</button><button data-ok=''1''>Entiendo. ¿Qué presupuesto tenían en mente?</button><button data-ok=''0''>Es lo que hay.</button><div class=''r''></div></div><div class=''q'' data-ok="Condição clara: siempre y cuando / si." data-no="Desconto em espanhol é descuento — e falta a condição."><p>Você quer condicionar um desconto:</p><button data-ok=''1''>Hacemos el descuento si firman este mes.</button><button data-ok=''0''>Damos un desconto.</button><button data-ok=''0''>Bajamos el precio, ok?</button><div class=''r''></div></div><div class=''q'' data-ok="Resume e confirma: ninguém sai com dúvidas." data-no="Falta resumir o que foi combinado."><p>Para confirmar o acordo no fim:</p><button data-ok=''0''>Ok, tchau.</button><button data-ok=''1''>Entonces quedamos así: … ¿Les parece bien?</button><button data-ok=''0''>Listo, cerrado.</button><div class=''r''></div></div></div>@@JS@@</body></html>',null,3,'espanhol',false);
insert into material_turmas(material_id,turma_id) values('acd5a295-895b-4863-9f5e-967d50bc6075','cae5ea78-362c-42b3-8450-ff368f910b47');
insert into fases(id,materia_id,titulo,ordem) values('00ec53bd-6430-41aa-bf4c-8cf9728fbf25','8168a604-f693-4f83-9b8a-1cbaaa47c629','Aplicar',2);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('73a47e7f-ee57-42b6-9101-ead3569c9d0c','8168a604-f693-4f83-9b8a-1cbaaa47c629','00ec53bd-6430-41aa-bf4c-8cf9728fbf25','html','Desafio: simulação na aula','<!doctype html><html lang=''es''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Módulo 3 · Desafio</p><h1>Prepare sua negociação</h1><ol><li>Defina o que você quer, o mínimo aceitável e o que pode oferecer em troca.</li><li>Escreva 3 frases de proposta e 2 de resposta a objeções.</li><li>Na próxima aula: role-play com a professora no papel do cliente.</li></ol><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Firmeza não é dureza: combine <b>entiendo</b> + <b>sin embargo</b> e proponha sempre uma alternativa.</p></div></div>@@JS@@</body></html>',null,4,'espanhol',false);
insert into material_turmas(material_id,turma_id) values('73a47e7f-ee57-42b6-9101-ead3569c9d0c','cae5ea78-362c-42b3-8450-ff368f910b47');
